import { useIdentity } from '@/app/providers/IdentityProvider'
import { useTenant } from '@/app/providers/TenantProvider'

/**
 * Renders a small empty-state banner inside the app shell when the active tenant
 * has no workspaces. Kept inline (not a full-page takeover) so admins can still
 * navigate to /app/admin and create one.
 */
export function NoWorkspaceBanner() {
  const { status } = useIdentity()
  const { manifest } = useTenant()
  if (status !== 'no_workspace') return null
  return (
    <div className="mx-6 mt-4 rounded-xl border border-dashed border-border bg-surface p-5 text-center">
      <p className="text-sm font-medium mb-1">No workspaces yet in {manifest?.name ?? 'this tenant'}</p>
      <p className="text-xs text-muted-foreground">
        Ask an admin to create a workspace, or visit Admin → Workplaces if you have access.
      </p>
    </div>
  )
}
